/// Return an owned copy of explicitly supplied program arguments.
pub fn Arguments.all(args: read List<String>) -> fresh List<String>

/// Return the number of explicitly supplied program arguments.
pub fn Arguments.count(args: read List<String>) -> Int

/// Return one explicitly supplied program argument when the index is valid.
pub fn Arguments.get(
    args: read List<String>,
    index: Int,
) -> Option<String>

/// Return one explicitly supplied program argument or the caller-provided default.
pub fn Arguments.get_or_default(
    args: read List<String>,
    index: Int,
    default: String,
) -> String

// `Clone` is an explicit, deep value copy, modeled on Swift's value semantics
// and Rust's `Clone`.
//
// A managed `struct` or `sum` satisfies `Clone` by listing `derives(Clone)`,
// which the compiler expands into a structural copy of every field. The builtin
// value scalars (`Int`, `String`, `Bool`, ...) satisfy `Clone` directly.
//
// `Clone.clone<T>(self: read x)` copies a value out of a shared (`read`) borrow
// into a `fresh` owned value, closing the "clone gap" where a `read` field
// cannot be moved into a constructor. `Clone` is a pure contract: it introduces
// no mutation, retention, native, or unsafe boundary.
protocol Clone {
    fn clone(self: Self) -> fresh Self
}

// `Eq` is total, structural value equality, modeled on Swift's `Equatable`.
//
// A managed `struct` or `sum` satisfies `Eq` by listing `derives(Eq)` (or
// `derives(Ord)`, which implies `Eq`), which the compiler expands into a
// structural equality over every field. The builtin equatable scalars
// (`Int`, `String`, `Bool`, ...) satisfy `Eq` directly. `Eq` is a pure,
// total contract: it introduces no mutation, retention, native, or unsafe
// boundary.
protocol Eq {
    fn equals(self: Self, other: Self) -> Bool
}

protocol Ord {
    fn compare(self: Self, other: Self) -> Int
}

// Explicit dynamic protocol object. `Dyn` is a language-level dispatch
// boundary and carries no host authority.
struct Dyn<P>

pub fn Dyn.from<P, T>(value: take T) -> fresh Dyn<P>

// `Hashable` lets a managed value be used as a `Map<K, V>` key or `Set<K>`
// element, modeled on Swift's `Hashable` (which refines `Equatable`). A type
// that is `Hashable` must also be `Eq`: two values that compare equal must hash
// equal.
//
// A managed `struct` or `sum` satisfies `Hashable` by listing
// `derives(Eq, Hash)`, which the compiler expands into a structural hash and
// equality over every field — no hand-written boilerplate. The builtin hashable
// scalars (`Int`, `String`, `Bool`, ...) satisfy `Hashable` directly.
//
// `Hashable` is pure and total: it introduces no mutation, retention, native,
// or unsafe boundary, and adds no capability gate. It is the bound on
// `Map<K, V>` keys and `Set<K>` elements so that graph interning, dedup, and
// memoization over user-defined managed types are expressible while a
// non-hashable key is rejected in RSScript instead of leaking from rustc.
protocol Hashable {
    fn hash_value(self: Self) -> Int
}
